mapper.sql:
WHERE s.status = 1

AND s.class_id = #{classId}
AND c.grade_id = #{gradeId}

    AND (s.student_no LIKE CONCAT('%', #{keyword}, '%')
         OR s.name LIKE CONCAT('%', #{keyword}, '%'))

WHERE i.status  = 1
  AND i.deleted = 0
AND i.dept_id = #{deptId}
AND i.class_id = #{classId}
AND i.category = #{category}


        AND i.dimension IS NULL
        AND i.dimension = #{dimension}


AND i.change_type <> 0

mapper.select:
SELECT i.*, st.student_no AS studentNo, st.name AS studentName, c.name AS className, d.dept_name AS deptName, u.real_name AS submitterName, r.real_name AS reviewerName FROM `score_item` i JOIN `student` st ON st.id = i.student_id JOIN `sys_class` c ON c.id = i.class_id LEFT JOIN `sys_dept` d ON d.id = i.dept_id LEFT JOIN `sys_user` u ON u.id = i.submitted_by LEFT JOIN `sys_user` r ON r.id = i.reviewed_by WHERE i.student_id = #{studentId} AND i.term = #{term} AND i.deleted = 0 AND i.category = #{category}
AND i.dimension IS NULL AND i.dimension = #{dimension}
AND i.status = #{status}
ORDER BY (i.status = 5) ASC, i.occurred_on DESC, i.id DESC

mapper.sql:
WHERE i.created_by = #{userId}
  AND i.deleted    = 0
AND i.status = #{status}

WHERE i.deleted = 0 AND i.reason LIKE CONCAT('%', #{keyword}, '%')
AND i.class_id IN
#{cid}
